Definition regs_ok (E : env) (sr : list expr) (regs : bvmap 5 word) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 3 "S20!1,^C|21;!1+^B!1,^C|600;$E;R+^A$sr;R!1+_5+P$regs;R!2'e801%r;R!1+^B0!3+11!2'e9#2#1!2'`Q#4!2'e:#3#1").

Lemma regs_ok_upd : forall E sr regs rd v e,
  regs_ok E sr regs -> edenot E e = v ->
  regs_ok E (if bv_eqb rd 0 then sr else sr_upd sr (ridx rd) e)
            (if bv_eqb rd 0 then regs else regupd regs rd v).
