Fixpoint mem_denot (E : env) (base : word -> option byte) (log : list sentry)
  : word -> option byte :=
  match log with
  | [] => base
  | SE a w v :: rest =>
      wbytes (mem_denot E base rest) (adenot E a) (word_to_le_bytes w (edenot E v))
  end.

Lemma mem_denot_grows : forall E base log, mem_grows base (mem_denot E base log).
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S50|30;!1+_5+f1!3'f3#<#;#2!2'f7#<#5!2'f8#4!2'`Q#<#3$E;R+^A$base;R%~R!1+^B!1,^C|600;!1+bG!1+^B!1,^C0$log;R1!5'`V+f1$log;R1!2'f2#3!3'f3#4#3#1vd!1'f4#2!2'f2#2!3'f3#3#2!1,_3+f1$a0;R+f1-f1RN$s;R+f1%l;R1%~R!2'f2#5!3'f3#6#5#1!2'f2#6!3'f3#7#6!3,_L+f1#3#2#11$e_addr;R+^=$e_width;R+Y$e_val;R+P!3$a;R+^=$w;R+Y$v;R+P$rest;R1$IH;R!2'f2#:!3'f3#;#:#1vd!5'f5#;2!3'f6234#1!3'f9423!2'f2#;!3'f3#<#;!3,_L+f1!3,f:#5#4#3#2#3#2#1#1").
Qed.

Definition estart (E : env) (a : saddr) : Z := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S00$E;R+^A$a;R+^=!2'^J!2'^H!1,^C|600;!2'`Q#2!1'f;#1!1'f<#1").
Definition elenZ (E : env) (n : expr) : Z := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S00$E;R+^A$n;R+P!2'^H!1,^C|600;!2'`Q#2#1").

Definition flat (E : env) (a : saddr) (n : Z) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 3 "S30!2'f=#3#2|10;!2'^Z!1,^[1!1,^[|600;$E;R+^A$a;R+^=$n;R+S!2+^8!2'_1,^F0!2+^8!2'_002!2+^8!2'_1,^F#1!2'_1!2'^J0#12").

