Lemma Z_to_bv_u_plus0 : forall a : word, Z_to_bv 64 (bv_unsigned a + 0) = a.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S30!1,^C|600;!1+^B0!2'^H0#1$a;R1!6'X+S2$z;R+S!3+11!2'^D0#1#2!2'b:0#1!2'^J2,^F!1'^M2").
Qed.

Lemma rdn_pointwise : forall segs mem n (a : word) bs,
  length bs = n ->
  (bv_unsigned a + Z.of_nat n <= 2^64)%Z ->
  (forall j, (j < n)%nat ->
