Lemma step_store : forall segs regs pc mem rom w sz (rs1 rs2 : reg) (imm : bv 12),
  fetch_word segs pc = Some w -> is_ecall w = false ->
  decode_any w = Some (Store sz rs1 rs2 imm, 4%Z) ->
  RiscvSemantics.store_ok segs mem
    (v_addi (getr regs rs1) (bv_signed imm)) (msize_bytes sz) = true ->
  RiscvSemantics.step segs (mkst regs pc mem rom) =
  MachineOk (mkst regs (v_addi pc 4)
    (wbytes mem (v_addi (getr regs rs1) (bv_signed imm))
            (word_to_le_bytes (msize_bytes sz) (getr regs rs2))) rom).
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "SG0!1,^C|21;!1+^B!1,^C|600;|30;%~R1!1+bG!1+^B!1,^C2|500;!1+^B!1,^C4!1+^B0!1,^C|34;!2+_Z+gQ+S!1+bG8|20;!1,^[:!2'gT!2'e9#?#9!2'bY7#7!1+gV+gW!1'gR#9!2'gT!2'e9#>#8!2'bY7#6!1'gU,h\!2'i7#@!5'g[/fx;#?#>#=#<!2'gT#>;!2'e9#?#8!1'gU,i3!1'gU,i4!1'gU,i5$segs;R!1+_5+f?$regs;R!2'e801$pc;R1$mem;R3$rom;R3$w;R5$sz;R+gN$rs1;R6$rs2;R6$imm;R!1+^B7$Hf;R!3+1!1+bG5!2'gO#:#8!2,bI5#5$He;R!3+1+2!1'gP#6,7$Hd;R!3+19!1'gR#7!2,bI8!4,`Z+gQ+S!4,iH#6#5#4#3;$Hok;R!3+1+2!4'hS#=#:!2'gT!2'e9#<#6!2'bY7#4!1'gU#7,4!2-gNRN$m;R+gN%Hd;R!3+19!1'gR#:!2,bI8!4,`Z+gQ+S!4,iH#1#8#7#6;%Hok;R!3+1+2!4'hS#@#=<!1'gU#2,4!3+1=!2'i7#A!5'g[/fx;#@#?#>#=!2,h3+gW!5'g[/fx;#@!2'gT#?;!3'f6#>!2'gT!2'e9#@#:!2'bY7#8!2'f8!1'gU#3!2'e9#@#9#=#84$Hd;R!3+19>!2,bI8!4,`Z+gQ+S!4,iH,h\#7#6#5;$Hok;R!3+1+2!4'hS#?#<?@,4vd!>'iI/fx;#@#?#>#=#<#;#9#8#7#6#5#2#1!3+1=A!2,h3+gW!5'g[/fx;#?B!3'f6#=<!2'f8@C#<$Hd;R!3+19>!2,bI8!4,`Z+gQ+S!4,iH,i3#7#6#5;$Hok;R!3+1+2!4'hS#?#<?D,4vd!>'iJ/fx;#@#?#>#=#<#;#9#8#7#6#5#2#1!3+1=A!2,h3+gW!5'g[/fx;#?B!3'f6#=<!2'f8DC#<$Hd;R!3+19>!2,bI8!4,`Z+gQ+S!4,iH,i4#7#6#5;$Hok;R!3+1+2!4'hS#?#<?E,4vd!>'iK/fx;#@#?#>#=#<#;#9#8#7#6#5#2#1!3+1=A!2,h3+gW!5'g[/fx;#?B!3'f6#=<!2'f8EC#<$Hd;R!3+19>!2,bI8!4,`Z+gQ+S!4,iH,i5#7#6#5;$Hok;R!3+1+2!4'hS#?#<?F,4vd!>'iL/fx;#@#?#>#=#<#;#9#8#7#6#5#2#1!3+1=A!2,h3+gW!5'g[/fx;#?B!3'f6#=<!2'f8FC#<#2#1").
