Lemma scs_denot_cons : forall segs base E s l,
  scs_denot segs base E (s :: l) <-> sc_denot segs base E s /\ scs_denot segs base E l.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "SF0|30;!1+_5+fC!3'fD#5#4#3!3,_L+fC#2#1!3+fA+fC23!4'fD#6#5#4#3!3'fD#6#5#4!3+fA+fC6#2!4'fD#5#4#3#2!2+^88!3+fA+fC2#1!3,_L+fC#3#2!3,_L+fC#5#4!3+fA+fC!3'fD#9#8#7#5!2+^8!4'fD#9#8#7#6<!1,_3+fC!3,_L+fC#4#3!3+11#:#A!3'fD#G#F#E!4'fD#H#G#F#E!3'fD#H#G#F!3+fA+fCC#D!4'fD#8#7#6#5$segs;R!1+_5+f?$base;R%~R!1+^B!1,^C|600;!1+bG!1+^B!1,^C0$E;R+^A$s;R+fC$l;R1vd!4,bO%~R4!2+^857%~R9!3+fA+fC6:$H;R4&H0;R-fARN$l;R!1+_5+fC$~R!3+fA+fC!3'fD#7#6#5#1%~R!3+11#2;=#12$H0;R!3+11>:!1$H0;R!3+11>?&H1;R!6'81>$e;R1-_5RN$l;R!1+_5+fCw#12+:$~R+fC$~R!1+_5+fC+9,;;#1+9!2'<=#1#1$x;R+fC$l;R!1+_5+fC$~R!4'fD#8#7#6#2$~R!3+fA+fC!3'fD#9#8#7#2!4$x;R+fC$l0;R1$H0;R!4'fD#<#;#:#2$H1;R!3+fA+fC!3'fD#=#<#;#2$H2;R!3+11?!3,_L+fC#;#:!3$H2;R!3+11;!3,_L+fC#<#;&H0;R!6'bJ11$e;R1-_5RN$l;R!1+_5+fC1#12#6$s;R+fC$l;R!1+_5+fC#1!3,_L+fC#6#5!3,_L+fC#=#<#1!3+11#5#<!1&H0;R!6'bJ1+fC$e;R1-_5RN$l;R!1+_5+fC+fC#12#8$s;R+fC$l;R!1+_5+fC#2!3,_L+fC#7#6!3,_L+fC#>#=#2!3+1+fC#7#>!1$H0;R!3+1+fC#8#?&H1;R#1!3+1+fC#9#@!6'X+fC#A$s;R+fC%~R@%H0;R!4'fD#F#E#D#2%H1;R!3+fA+fCA#<!2+^8BD$H1;R!3+11#9#@&H3;R#1@!6'X1#B$l;R1%H0;R!4'fD#G#F#E#D%H1;R!3+fA+fCC#2!2+^8!4'fD#I#H#G#F!3+fA+fC!3'fD#I#H#G#E$H2;R!4'fD#F#E#D#C$H3;R!3+fA+fCA#C!4,bOBD#2#1#;#1#:#1#1#1#1#3#2#4#3#2#1!1$l;R1%~R!3+11#1?!2+^8E!3+fA+fC!3'fD#8#7#6#4:!1#1!2,61?$H;R9!5'V57!3+fA+fC!3'fD#6#5#4!3,_L+fC#3#2$~R5$~R!3+fA+fC!3'fD#7#6#5#3!2$A;RE$B;R<!6,iM+fC!3'fD#:#9#8#7#6#2#1#2#1#1!2'iN!4'iO#5#4#33!2+^88!4'iO#5#4#3#1").
Qed.

Lemma scs_denot_app : forall segs base E l1 l2,
  scs_denot segs base E (l1 ++ l2) <-> scs_denot segs base E l1 /\ scs_denot segs base E l2.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S20|30;!1+_5+fC$segs;R!1+_5+f?$base;R%~R!1+^B!1,^C|600;!1+bG!1+^B!1,^C0$E;R+^A$l1;R1$l2;R1vd!4'iP+fC!3'fD#5#4#3#2#1!2'iN!4'iO#5#4#3!3'iQ+fC#2#1!2+^8!4'iO#5#4#3#2!4'iO#5#4#3#1").
Qed.

