Lemma prune_sound : forall E (anybase : word -> option byte) M0 allkn M wa w V kn hints kn' scs hs',
  prune allkn wa w kn hints = (kn', scs, hs') ->
  know_ok segs E M0 allkn ->
  (w <= 8)%nat -> flat E wa (Z.of_nat w) ->
